// A teammate's any version — it compiles, but refuses nothing.
export type Result = { ok: boolean; value?: any; error?: string };
export function ok(value: any): Result { return { ok: true, value }; }
export function err(error: string): Result { return { ok: false, error }; }

export class Repo {
  private items = new Map<number, any>();
  add(item: any): Result { return this.items.has(item.id) ? err('dup') : (this.items.set(item.id, item), ok(item)); }
  get(id: number): Result { const f = this.items.get(id); return f === undefined ? err('not found') : ok(f); }
  get size(): number { return this.items.size; }
}

export function pluck(items: any[], key: string): any[] { return items.map((i) => i[key]); }
export function groupBy(items: any[], keyFn: (i: any) => any): Map<any, any[]> {
  const g = new Map<any, any[]>();
  for (const i of items) { const k = keyFn(i); const l = g.get(k); if (l === undefined) g.set(k, [i]); else l.push(i); }
  return g;
}

import { Repo, pluck, groupBy } from '../src/repo.ts';
import type { Result } from '../src/repo.ts';
import type { User } from '../src/user.ts';
declare const an: User;
const users = new Repo<User>();
const added: Result<User> = users.add(an);
const got = users.get(1);
const name: string = got.ok ? got.value.name : '';   // got.value is a User
const ids: number[] = pluck([an], 'id');
const byRole = groupBy([an], (u) => u.role);
const studentIds: number[] = (byRole.get('STUDENT') ?? []).map((u) => u.id);
export { added, name, ids, studentIds };

