import { test } from 'node:test';
import assert from 'node:assert/strict';
import { Repo, pluck, groupBy } from '../src/repo.ts';

const an = { id: 1, name: 'An', role: 'STUDENT' };
const binh = { id: 2, name: 'Binh', role: 'LECTURER' };
test('repo', () => {
  const r = new Repo<typeof an>();
  assert.equal(r.add(an).ok, true);
  assert.equal(r.add(an).ok, false);
  const got = r.get(1);
  assert.equal(got.ok && got.value.name, 'An');
  assert.equal(r.get(9).ok, false);
});
test('pluck/groupBy', () => {
  assert.deepEqual(pluck([an, binh], 'id'), [1, 2]);
  const g = groupBy([an, binh], (u) => u.role);
  assert.deepEqual(g.get('STUDENT')?.map((u) => u.id), [1]);
});

